-- Generated from the original Navicat backup; public website content only.
CREATE TABLE IF NOT EXISTS `jzw_article` (`id` INTEGER,`catid` INTEGER,`userid` INTEGER,`username` TEXT,`title` TEXT,`title_style` TEXT,`keywords` TEXT,`description` TEXT,`content` TEXT,`thumb` TEXT,`posid` INTEGER,`status` INTEGER,`listorder` INTEGER,`url` TEXT,`hits` INTEGER,`createtime` INTEGER,`updatetime` INTEGER,`name` TEXT,`lang` INTEGER,`copyfrom` TEXT,`zuozhe` TEXT,`wap_content` TEXT,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_attachment` (`aid` INTEGER,`moduleid` INTEGER,`catid` INTEGER,`id` INTEGER,`filename` TEXT,`filepath` TEXT,`filesize` INTEGER,`fileext` TEXT,`isimage` INTEGER,`isthumb` INTEGER,`userid` INTEGER,`createtime` INTEGER,`uploadip` TEXT,`status` INTEGER,PRIMARY KEY (`aid`));
CREATE TABLE IF NOT EXISTS `jzw_biaoshi` (`id` INTEGER,`catid` INTEGER,`userid` INTEGER,`username` TEXT,`title` TEXT,`title_style` TEXT,`thumb` TEXT,`keywords` TEXT,`description` TEXT,`content` TEXT,`url` TEXT,`template` TEXT,`posid` INTEGER,`status` INTEGER,`recommend` INTEGER,`readgroup` TEXT,`readpoint` INTEGER,`listorder` INTEGER,`hits` INTEGER,`createtime` INTEGER,`updatetime` INTEGER,`lang` INTEGER,`neiron` TEXT,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_block` (`id` INTEGER,`pos` TEXT,`name` TEXT,`lang` INTEGER,`content` TEXT,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_case` (`id` INTEGER,`catid` INTEGER,`userid` INTEGER,`username` TEXT,`title` TEXT,`title_style` TEXT,`thumb` TEXT,`keywords` TEXT,`description` TEXT,`content` TEXT,`url` TEXT,`template` TEXT,`posid` INTEGER,`status` INTEGER,`recommend` INTEGER,`readgroup` TEXT,`readpoint` INTEGER,`listorder` INTEGER,`hits` INTEGER,`createtime` INTEGER,`updatetime` INTEGER,`lang` INTEGER,`zuozhe` TEXT,`wap_content` TEXT,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_category` (`id` INTEGER,`catname` TEXT,`catdir` TEXT,`titlesub` TEXT,`remark` TEXT,`parentdir` TEXT,`parentid` INTEGER,`moduleid` INTEGER,`module` TEXT,`arrparentid` TEXT,`arrchildid` TEXT,`type` INTEGER,`title` TEXT,`keywords` TEXT,`description` TEXT,`listorder` INTEGER,`ishtml` INTEGER,`ismenu` INTEGER,`hits` INTEGER,`image` TEXT,`child` INTEGER,`url` TEXT,`template_list` TEXT,`template_show` TEXT,`pagesize` INTEGER,`readgroup` TEXT,`listtype` INTEGER,`lang` INTEGER,`urlruleid` INTEGER,`presentpoint` INTEGER,`chargepoint` INTEGER,`paytype` INTEGER,`repeatchargedays` INTEGER,`postgroup` TEXT,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_config` (`varname` TEXT,`info` TEXT,`groupid` INTEGER,`value` TEXT,`lang` INTEGER);
CREATE TABLE IF NOT EXISTS `jzw_link` (`id` INTEGER,`status` INTEGER,`listorder` INTEGER,`createtime` INTEGER,`name` TEXT,`logo` TEXT,`siteurl` TEXT,`typeid` INTEGER,`linktype` INTEGER,`siteinfo` TEXT,`lang` INTEGER,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_page` (`id` INTEGER,`title` TEXT,`thumb` TEXT,`keywords` TEXT,`description` TEXT,`content` TEXT,`template` TEXT,`listorder` INTEGER,`pics` TEXT,`shuxing` TEXT,`subtitle` TEXT,`createtime` INTEGER,`zuozhe` TEXT,`hits` INTEGER,`wap_content` TEXT,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_slide` (`id` INTEGER,`name` TEXT,`flashfile` TEXT,`xmlfile` TEXT,`tpl` TEXT,`width` INTEGER,`height` INTEGER,`num` INTEGER,`status` INTEGER,`lang` INTEGER,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_slide_data` (`id` INTEGER,`fid` INTEGER,`title` TEXT,`subtitle` TEXT,`small` TEXT,`pic` TEXT,`link` TEXT,`description` TEXT,`data` TEXT,`listorder` INTEGER,`status` INTEGER,`lang` INTEGER,PRIMARY KEY (`id`));
CREATE TABLE IF NOT EXISTS `jzw_tags` (`id` INTEGER,`name` TEXT,`slug` TEXT,`moduleid` INTEGER,`module` TEXT,`num` INTEGER,`lang` INTEGER,PRIMARY KEY (`id`,`moduleid`));
CREATE TABLE IF NOT EXISTS `jzw_tags_data` (`id` INTEGER,`tagid` INTEGER,`listorder` INTEGER,PRIMARY KEY (`id`,`tagid`));
CREATE TABLE IF NOT EXISTS cms_translations (entity VARCHAR(40) NOT NULL, entity_id BIGINT NOT NULL, locale VARCHAR(10) NOT NULL, fields TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 0, updated_at BIGINT NOT NULL, PRIMARY KEY(entity,entity_id,locale));
CREATE TABLE IF NOT EXISTS cms_settings (name VARCHAR(100) PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS cms_revisions (id VARCHAR(64) PRIMARY KEY, entity VARCHAR(40), entity_id BIGINT, locale VARCHAR(10), data TEXT, created_at BIGINT);
CREATE TABLE IF NOT EXISTS cms_inquiries (id VARCHAR(64) PRIMARY KEY, name VARCHAR(200), email VARCHAR(200), phone VARCHAR(80), message TEXT, locale VARCHAR(10), created_at BIGINT, status VARCHAR(20) DEFAULT 'new');
CREATE TABLE IF NOT EXISTS cms_media (path VARCHAR(191) PRIMARY KEY, name VARCHAR(200), size BIGINT, type VARCHAR(100), created_at BIGINT);
CREATE TABLE IF NOT EXISTS cms_rate_limits (id VARCHAR(191) PRIMARY KEY, attempts INTEGER NOT NULL DEFAULT 0, expires_at BIGINT NOT NULL);
